weather_alert_cooldown_sec := 3600 * 3
last_weather_alert := 0

now = (#Clock).clock_timestamp

// 이미 강수 중이면 예보 알림은 무의미하다 — forecast(0) = 현재 관측
current_weather = (#WeatherProvider).weatherProvider_forecast(0)
if (current_weather == "rain" or current_weather == "drizzle" or current_weather == "thunderstorm" or current_weather == "snow") { break }

// 1~6시간 뒤 예보를 차례로 조회, 강수가 처음 나타나는 시각을 찾는다
rain_hour = 0
h = 1
loop (h <= 6) {
  fc = (#WeatherProvider).weatherProvider_forecast(h)
  if (fc == "rain" or fc == "drizzle" or fc == "thunderstorm" or fc == "snow") {
    rain_hour = h
    break
  }
  h = h + 1
}

if (rain_hour > 0 and (now - last_weather_alert > weather_alert_cooldown_sec)) {
  message = rain_hour + "시간 내 강수가 예보됩니다. 우산을 챙겨주세요."
  (#ToastPublisher).toastPublisher_publish("normal", message, "")
  all(#Speaker #Office).speaker_speak(message)
  last_weather_alert = now
}

st_pm10 := 80.0
st_pm25 := 35.0
st_pm1 := 25.0
st_tvoc := 0.6
st_co2 := 800.0

// CO2 경고 토스트 최소 간격 30분 (period 재호출 간 유지)
co2_toast_cooldown_sec := 30 * 60
last_co2_toast := 0

occupancy = (#GlobalVariable).globalVariable_getBoolean("occupancy")
if (occupancy == true) {
  now = (#Clock).clock_timestamp

  // 현재 센서들로부터 각 지표 합계/개수 집계 (개수 0 나눗셈은 아래 n>0 가드로 회피)
  n_pm10 = 0
  n_pm25 = 0
  n_pm1 = 0
  n_tvoc = 0
  n_co2 = 0
  sum_pm10 = 0
  sum_pm25 = 0
  sum_pm1 = 0
  sum_tvoc = 0
  sum_co2 = 0
  // 지표마다 보고 센서 수가 다를 수 있어 각 지표를 자기 카운트로 나눔(분모 희석/경고 누락 방지)
  for (v : all(#AirQualitySensor #Office).airQualitySensor_dustLevel) { sum_pm10 = sum_pm10 + v; n_pm10 = n_pm10 + 1 }
  for (v : all(#AirQualitySensor #Office).airQualitySensor_fineDustLevel) { sum_pm25 = sum_pm25 + v; n_pm25 = n_pm25 + 1 }
  for (v : all(#AirQualitySensor #Office).airQualitySensor_veryFineDustLevel) { sum_pm1 = sum_pm1 + v; n_pm1 = n_pm1 + 1 }
  for (v : all(#AirQualitySensor #Office).airQualitySensor_tvocLevel) { sum_tvoc = sum_tvoc + v; n_tvoc = n_tvoc + 1 }
  for (v : all(#AirQualitySensor #Office).airQualitySensor_carbonDioxide) { sum_co2 = sum_co2 + v; n_co2 = n_co2 + 1 }

  if (n_pm10 > 0 and n_pm25 > 0 and n_pm1 > 0 and n_tvoc > 0 and n_co2 > 0) {
    avg_pm10 = sum_pm10 / n_pm10
    avg_pm25 = sum_pm25 / n_pm25
    avg_pm1 = sum_pm1 / n_pm1
    avg_tvoc = sum_tvoc / n_tvoc
    avg_co2 = sum_co2 / n_co2

    // 공기청정기: 어느 지표든 임계 초과 -> ON / 모든 지표가 임계 절반 미만 -> OFF (데드밴드)
    if (all(#AirPurifier #Office).switch_switch ==| false and (avg_pm10 > st_pm10 or avg_pm25 > st_pm25 or avg_pm1 > st_pm1 or avg_tvoc > st_tvoc)) {
      msg = "공기질이 불량합니다. 공기청정기를 켭니다. PM10: " + avg_pm10 + " μg/m³, PM2.5: " + avg_pm25 + " μg/m³, PM1: " + avg_pm1 + " μg/m³, TVOC: " + avg_tvoc + " mg/m³"
      (#ToastPublisher).toastPublisher_publish("warning", "공기질 나쁨", msg)
      all(#AirPurifier #Office).switch_on()
    }
    if (all(#AirPurifier #Office).switch_switch ==| true and avg_pm10 < (st_pm10 / 2) and avg_pm25 < (st_pm25 / 2) and avg_pm1 < (st_pm1 / 2) and avg_tvoc < (st_tvoc / 2)) {
      all(#AirPurifier #Office).switch_off()
    }

    // CO2: 임계 초과 + 마지막 토스트 후 30분 경과 -> 경고 토스트
    if (avg_co2 > st_co2 and (now - last_co2_toast > co2_toast_cooldown_sec)) {
      msg = "이산화탄소 농도가 너무 높습니다. 창문을 열어 환기를 해주세요. 현재 CO₂ 농도: " + avg_co2 + " ppm"
      (#ToastPublisher).toastPublisher_publish("warning", "이산화탄소 농도 경고", msg)
      last_co2_toast = now
    }

    // CO2 농도별 표시등 색상 변경 (< 800 녹 / 800-1000 황 / 1000-1500 주황 / ≥ 1500 적)
    if (avg_co2 < 800.0) { all(#Light #CO2_Indicator).light_moveToColor(0.17, 0.70, 1.0) }
    else if (avg_co2 < 1000.0) { all(#Light #CO2_Indicator).light_moveToColor(0.43, 0.50, 1.0) }
    else if (avg_co2 < 1500.0) { all(#Light #CO2_Indicator).light_moveToColor(0.54, 0.41, 1.0) }
    else { all(#Light #CO2_Indicator).light_moveToColor(0.67, 0.32, 1.0) }
  }
}

armed := false          // security_mode 로컬 미러(글로벌과 동기)
manual_disarm := false  // 오프아워 수동 해제 홀드(버튼으로 set, 퇴실 시 리셋)
was_pushed := false     // 버튼 상승 엣지 검출
synced := false         // 글로벌 최초 1회 시드 여부

// 오픈 시간대 판정: 평일(월~금) AND 비공휴일 AND 07<=시<22
wd = (#Clock).clock_weekday
hr = (#Clock).clock_hour
is_weekday = false
if (wd != "saturday" and wd != "sunday") { is_weekday = true }
open_window = false
if (is_weekday == true and (#Clock).clock_isHoliday == false and hr >= 7 and hr < 22) { open_window = true }

// 버튼 상승 엣지 -> 오프아워 수동 해제 홀드
pushed = false
if ((#Button #Office #ModeToggle).button_button == "pushed") { pushed = true }
if (pushed == true and was_pushed == false) {
  manual_disarm = true
  (#ToastPublisher).toastPublisher_publish("normal", "보안 모드 해제", "보안 모드가 해제되었습니다.")
  (#Speaker #Office).speaker_speak("보안 모드를 해제했습니다.")
}
was_pushed = pushed

// 재실자가 나가면(부재) 수동 해제 홀드 리셋 -> 다음 입실자에겐 다시 무장
occ_present = false
occupancy = (#GlobalVariable).globalVariable_getBoolean("occupancy")
if (occupancy == true) { occ_present = true }
if (occ_present == false) { manual_disarm = false }

// 자동 목표: 오픈=해제, 오프아워=무장. 수동 해제 홀드면 강제 해제.
desired = false
if (open_window == false) { desired = true }
if (manual_disarm == true) { desired = false }

// 최초 1회 시드
if (synced == false) {
  armed = desired
  (#GlobalVariable).globalVariable_setBoolean("security_mode", desired)
  synced = true
}

// 값 바뀔 때만 set + 안내
if (desired != armed) {
  armed = desired
  (#GlobalVariable).globalVariable_setBoolean("security_mode", desired)
  if (desired == true) {
    (#GlobalVariable).globalVariable_setString("attendance_state", "퇴근")
    (#ToastPublisher).toastPublisher_publish("normal", "보안 모드 설정", "보안 모드가 설정되었습니다.")
  } else {
    (#GlobalVariable).globalVariable_setString("attendance_state", "출근")
    (#ToastPublisher).toastPublisher_publish("normal", "보안 모드 해제", "보안 모드가 해제되었습니다.")
  }
}

grace_start := 0            // 현재 grace 시작 시각(0 = 미진행)
grace_sec := 120            // 재실 감지 후 알림까지 유예 2분
alert_cooldown := 600       // 알림 재전송 최소 간격 10분
last_alert := 0

now = (#Clock).clock_timestamp
security_mode = (#GlobalVariable).globalVariable_getBoolean("security_mode")   // "보안 모드 자동 제어"가 생산
occupancy = (#GlobalVariable).globalVariable_getBoolean("occupancy")
// 무장 AND 재실일 때만 grace 진행
if (occupancy == true and security_mode == true) {
  if (grace_start == 0) {
    grace_start = now
    // 즉시 안내: 본인이면 버튼을 눌러 해제하라고 스피커로 알림(grace 시작 1회)
    all(#Speaker #Office).speaker_setVolume(75)
    (#Speaker #Office).speaker_speak("보안 모드가 설정되어 있습니다. 본인이라면 버튼을 눌러 보안 모드를 해제해 주세요.")
    (#ToastPublisher).toastPublisher_publish("warning", "보안 모드 재실 감지", "보안 모드 중 재실이 감지되었습니다. 본인이라면 버튼으로 해제해 주세요.")
  }
  if ((now - grace_start > grace_sec) and (now - last_alert > alert_cooldown)) {
    (#ToastPublisher).toastPublisher_publish("warning", "[긴급] 침입 의심", "오피스에서 재실이 감지되었습니다.")
    video = (#Camera #Office).camera_captureVideo(10.0)
    (#EmailProvider).emailProvider_sendMailWithBinaryFile("mysmaxlab@gmail.com", "[긴급] 침입 의심", "오피스에 침입이 발생하였습니다.", video, "alert.mp4")
    last_alert = now
  }
} else {
  // 부재 또는 비무장: grace 리셋
  grace_start = 0
}

min_temp_summer := 24.5
max_temp_summer := 25.5
min_temp_winter := 19.5
max_temp_winter := 20.5
min_humid_summer := 50.0
max_humid_summer := 60.0
min_humid_winter := 40.0
max_humid_winter := 50.0

// 쿨다운 10분
ac_command_cooldown_sec := 600
hf_command_cooldown_sec := 600
last_ac_command := 0
last_hf_command := 0

occupancy = (#GlobalVariable).globalVariable_getBoolean("occupancy")
if(occupancy == true) {
  now = (#Clock).clock_timestamp

  min_temp = 0
  max_temp = 0
  min_humid = 0
  max_humid = 0
  airConditioner_mode = "cool"
  is_winter = false
  if ((#Clock).clock_month >= 4 and (#Clock).clock_month <= 9) {
    min_temp = min_temp_summer
    max_temp = max_temp_summer
    min_humid = min_humid_summer
    max_humid = max_humid_summer
    airConditioner_mode = "cool"
    is_winter = false
  } else {
    min_temp = min_temp_winter
    max_temp = max_temp_winter
    min_humid = min_humid_winter
    max_humid = max_humid_winter
    airConditioner_mode = "heat"
    is_winter = true
  }
  target_temp = (max_temp + min_temp) / 2
  target_humid = (max_humid + min_humid) / 2

  // 현재 평균 온도 계산 
  temp_sum = 0
  temp_avg = -1
  i = 0
  for (t : all(#AirQualitySensor #Office).airQualitySensor_temperature) {
    temp_sum = temp_sum + t
    i = i + 1
  }
  for (t : all(#TemperatureSensor #Office).temperatureSensor_temperature) {
    temp_sum = temp_sum + t
    i = i + 1
  }
  if (i > 0) { temp_avg = temp_sum / i }
  if (i > 0 and (now - last_ac_command > ac_command_cooldown_sec)) {
    if ((is_winter == false and temp_avg > max_temp) or (is_winter == true and temp_avg < min_temp)) {
      (#AirConditioner #Office).switch_on()
      (#AirConditioner #Office).airConditioner_setAirConditionerMode(airConditioner_mode)
      (#AirConditioner #Office).airConditioner_setTargetTemperature(target_temp)

      last_ac_command = now
    } else if ((is_winter == false and temp_avg < min_temp) or (is_winter == true and temp_avg > max_temp)) {
      (#AirConditioner #Office).switch_off()

      last_ac_command = now
    }
  }

  // 현재 평균 습도 계산
  if (is_winter == true) {
    humid_sum = 0
    humid_avg = -1
    j = 0
    for (h : all(#AirQualitySensor #Office).airQualitySensor_humidity) {
      humid_sum = humid_sum + h
      j = j + 1
    }
    for (h : all(#HumiditySensor #Office).humiditySensor_humidity) {
      humid_sum = humid_sum + h
      j = j + 1
    }
    if (j > 0) { humid_avg = humid_sum / j }
    if (j > 0 and (now - last_hf_command > hf_command_cooldown_sec)) {
      if (humid_avg < min_humid) {
        (#Humidifier #Office).switch_on()
        (#Humidifier #Office).humidifier_setHumidifierMode("medium")
        last_hf_command = now
      } else if (humid_avg > max_humid) {
        (#Humidifier #Office).switch_off()
        last_hf_command = now
      }
    }
  }
}

sE = (#GlobalVariable).globalVariable_getBoolean("occupancy_section_E")
s1 = (#GlobalVariable).globalVariable_getBoolean("occupancy_section1")
s2 = (#GlobalVariable).globalVariable_getBoolean("occupancy_section2")
s3 = (#GlobalVariable).globalVariable_getBoolean("occupancy_section3")
s4 = (#GlobalVariable).globalVariable_getBoolean("occupancy_section4")
s5 = (#GlobalVariable).globalVariable_getBoolean("occupancy_section5")
s6 = (#GlobalVariable).globalVariable_getBoolean("occupancy_section6")

any_present = false
if (sE == true or s1 == true or s2 == true or s3 == true or s4 == true or s5 == true or s6 == true) { any_present = true }

current = (#GlobalVariable).globalVariable_getBoolean("occupancy")
// write-on-change: 집계 결과가 저장값과 다를 때만 set
if (any_present == true and current == false) { (#GlobalVariable).globalVariable_setBoolean("occupancy", true) }
if (any_present == false and current == true) { (#GlobalVariable).globalVariable_setBoolean("occupancy", false) }

phase_1_elapse_time := 10 * 60 // 10분
phase_2_elapse_time := 30 * 60 // 30분

ts_latest_presence := (#Clock).clock_timestamp
was_present := false // 부재->재실 전이 감지용(도착 순간 1회 ON)

now = (#Clock).clock_timestamp
occupancy = (#GlobalVariable).globalVariable_getBoolean("occupancy")

if (occupancy == true) {
  // 부재->재실 전이(도착) 순간에만 1회 ON (재실 중 수동 OFF를 매 틱 되돌리지 않음)
  if (was_present == false) {
    if (all(#Switch #Office).switch_switch ==| false) { all(#Switch #Office).switch_on() }
    if (all(#Plug #Office).switch_switch ==| false) { all(#Plug #Office).switch_on() }
    if (all(#AirConditioner #Office).switch_switch ==| false) { all(#AirConditioner #Office).switch_on() }
    if (all(#SharedLight #Office).switch_switch ==| false) { all(#SharedLight #Office).switch_on() }
  }

  was_present = true
  ts_latest_presence = now
} else {
  was_present = false
  elapsed = now - ts_latest_presence
  if (elapsed > phase_1_elapse_time) {
    if (all(#Switch #Office #NoneNecessary).switch_switch ==| true) { all(#Switch #Office #NoneNecessary).switch_off() }
    if (all(#Plug #Office #NoneNecessary).switch_switch ==| true) { all(#Plug #Office #NoneNecessary).switch_off() }
    if (all(#AirConditioner #Office).switch_switch ==| true) { all(#AirConditioner #Office).switch_off() }
    if (all(#SharedLight #Office #NoneNecessary).switch_switch ==| true) { all(#SharedLight #Office #NoneNecessary).switch_off() }
  }
  if (elapsed > phase_2_elapse_time) {
    if (all(#Switch #Office).switch_switch ==| true) { all(#Switch #Office).switch_off() }
    if (all(#Plug #Office).switch_switch ==| true) { all(#Plug #Office).switch_off() }
    if (all(#SharedLight #Office).switch_switch ==| true) { all(#SharedLight #Office).switch_off() }
  }
}

absence_grace_sec := 10                       // 부재 확정용 드롭아웃 디바운스(설정값 · 기존 60에서 단축)
last_present_ts := (#Clock).clock_timestamp    // 마지막 재실 감지 시각
occ_mirror := false                            // occupancy_section1 로컬 미러(write-on-change 용 · 인디케이터 색 기준). := static 이라 주기 간 보존.
seeded := false                                // 최초 1회 시드 여부

now = (#Clock).clock_timestamp

present = false
if (all(#PresenceSensor #Office #Section1).presenceSensor_presence ==| true) { present = true }

if (seeded == false) {
  // 최초 1회: 현재값으로 글로벌 시드(램프 정렬은 아래 인디케이터 블록이 매 주기 처리)
  occ_mirror = present
  (#GlobalVariable).globalVariable_setBoolean("occupancy_section1", present)
  if (present == true) { last_present_ts = now }
  seeded = true
}
else {
  if (present == true) {
    last_present_ts = now
    // 재실: occupancy true(write-on-change)
    if (occ_mirror == false) {
      occ_mirror = true
      (#GlobalVariable).globalVariable_setBoolean("occupancy_section1", true)
    }
  } else {
    // 부재: 마지막 재실 후 grace 초과 시에만 부재 확정(write-on-change)
    if (occ_mirror == true and (now - last_present_ts > absence_grace_sec)) {
      occ_mirror = false
      (#GlobalVariable).globalVariable_setBoolean("occupancy_section1", false)
    }
  }
}

// ---- 인디케이터 표시(stateless · 매 주기 실행 · 현재값 밴드 가드로 중복 실행 방지) ----
if (all(#Light #Office #Section1).switch_switch ==| false) { all(#Light #Office #Section1).switch_on() }
if (all(#Light #Office #Section1).light_currentBrightness <| 39.0 or all(#Light #Office #Section1).light_currentBrightness >| 41.0) {
  all(#Light #Office #Section1).light_moveToBrightness(40.0, 0)
}
if (occ_mirror == true) {
  if (all(#Light #Office #Section1).light_currentX <| 0.16 or all(#Light #Office #Section1).light_currentX >| 0.18 or all(#Light #Office #Section1).light_currentY <| 0.69 or all(#Light #Office #Section1).light_currentY >| 0.71) {
    all(#Light #Office #Section1).light_moveToColor(0.17, 0.70, 1.0)
  }
} else {
  if (all(#Light #Office #Section1).light_currentX <| 0.66 or all(#Light #Office #Section1).light_currentX >| 0.68 or all(#Light #Office #Section1).light_currentY <| 0.31 or all(#Light #Office #Section1).light_currentY >| 0.33) {
    all(#Light #Office #Section1).light_moveToColor(0.67, 0.32, 1.0)
  }
}

if ((#Clock).clock_isHoliday == true) { break }

hour = (#Clock).clock_hour
minute = (#Clock).clock_minute

if ((#Speaker).speaker_volume < 90) { (#Speaker).speaker_setVolume(90) }

if (hour == 9 and minute == 30) {
  (#ToastPublisher).toastPublisher_publish("announce", "주간 미팅 30분 전", "주간 미팅이 30분 후에 시작됩니다.")
  (#Speaker #Office).speaker_speak("미팅 시작 30분 전입니다. 미리 미팅 준비를 해주시기 바랍니다.")
}
