  (#Speaker #Office).speaker_speak("미팅 시작 시간입니다.")
}

alert_cooldown_sec := 30 * 60   // 30분. clock_timestamp 는 초 단위
last_fire_alert := 0             // 마지막 전송 시각(0 = 아직 없음). 전송 시 타임스탬프로 갱신·유지

wait until ((#SmokeDetector).smokeDetector_smoke == true)

// 마지막 전송 후 30분 경과 시에만 재전송 (연기가 지속되면 30분 간격으로 반복)
