    (#EmailProvider).emailProvider_sendMail("mysmaxlab@gmail.com", "[긴급] 연기 감지", "SmokeDetector에서 연기가 감지되었습니다. 현장 확인이 필요합니다. 본 알림은 보조 안전 알림이며 공식 화재경보 설비를 대체하지 않습니다.")
    if ((#PresenceSensor #Office).presenceSensor_presence ==| true) {
      (#Speaker #Office).speaker_speak("화재가 감지되었습니다. 지금 즉시 대피해주시기 바랍니다.")
    }

    last_fire_alert = now
}
